const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
const isResume = input.intent === 'resume_after_approval' || input.input?.approved === true;
const query = String(input.input?.query || input.input?.message || input.message || '').toLowerCase();
const explicitCreation = /\b(create|shape|design|generate|build|define)\b[\s\S]{0,64}\b(new\s+)?(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(query)
  || /\b(new|additional)\s+(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(query)
  || /\b(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b[\s\S]{0,64}\b(create|shape|design|generate|build|define)\b/i.test(query);
const isCreateSkill = explicitCreation && (input.intent === 'create_skill' || input.context?.route_decision?.decision === 'create_skill');
const approvalRequired = !isResume && isCreateSkill;
const approval = approvalRequired ? {
  required: true,
  gate: 'skill_spec_approval',
  summary: 'Generated skill or agent proposal is ready for human review.',
  proposed_action: 'Approve the proposal to stage SkillSpec decomposition and make the generated capability available through Agentic Butler orchestration.'
} : { required: false };
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: approvalRequired ? 'approval_required' : 'completed',
  approval,
  output: {
    summary: aiText || (isResume ? 'Agentic Butler resumed after human approval.' : 'Agentic Butler completed autonomous skill orchestration under Actor Twin steering.'),
    approval_request: approvalRequired ? approval : null,
    skill_run: { mode: isResume ? 'resumed_after_approval' : approvalRequired ? 'approval_gated_new_skill_or_agent' : 'autonomous_actor_delegated', execute: !approvalRequired },
    skill_creation: approvalRequired ? {
      status: 'proposal_pending_approval',
      mode_of_action: 'Agentic Butler elicits, decomposes, and stages a generated skill or agent behind approval.',
      value_proposition: 'Transforms repeated work into reusable Actor Twin capability.',
      usp: 'Compares the proposed capability against existing skills and activates only after human ratification.'
    } : null,
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Agentic Butler AI Agent' }
  },
  trace: { stored: true, trace_id: 'n8n_exec_' + executionId, used_agents: ['agentic_butler_ai_agent', 'skill_orchestrator_internal_component', 'actor_twin_checkpoint_boundary'], target_agent: 'agentic_butler', route_decision: isCreateSkill ? 'create_skill' : 'activate_skill', handoff_status: approvalRequired ? 'approval_required' : 'completed_autonomous', parent_trace_id: input.context?.handoff_trace_id || input.context?.actor_trace_id || '', ai_agent_integrated: true }
};
return [{ json: response }];

